58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Dedicated audit logger; emits an audit line on successful owner create. */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final TelephoneNormalizer telephoneNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CityRegionResolver cityRegionResolver;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 AddressNormalizer addressNormalizer,
98	                                 CityRegionResolver cityRegionResolver) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.telephoneNormalizer = telephoneNormalizer;
104	        this.addressNormalizer = addressNormalizer;
105	        this.cityRegionResolver = cityRegionResolver;
106	    }
