108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
111	        Collection<Owner> owners;
112	        if (lastName != null) {
113	            owners = this.clinicService.findOwnerByLastName(lastName);
114	        } else {
115	            owners = this.clinicService.findAllOwners();
116	        }
117	        if (owners.isEmpty()) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
126	        Owner owner = this.clinicService.findOwnerById(ownerId);
127	        if (owner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        // A supplied registration date may not be later than the server's current date.
142	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
143	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
144	        }
145	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
146	        LocalDate registrationDate = owner.getRegistrationDate();
147	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
148	            .map(Owner::getRegistrationDate)
149	            .filter(registrationDate::equals)
150	            .count();
151	        if (ownersCreatedThatDay >= 100) {
152	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
153	        }
154	        String address = addressNormalizer.normalize(owner.getAddress());
155	        if (address.isBlank()) {
156	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
157	        }
158	        owner.setAddress(address);
159	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
160	        if (telephone == null) {
161	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
162	        }
163	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        owner.setTelephone(telephone);
167	        String email = owner.getEmail();
168	        if (email != null) {
169	            email = email.trim();
170	            if (!EMAIL_PATTERN.matcher(email).matches()) {
171	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
172	            }
173	            owner.setEmail(email.toLowerCase(Locale.ROOT));
174	        }
175	        // A postcode is optional, but when supplied it must be four digits and valid for the
176	        // owner's city per the fixed region table; a city with no known region accepts any
177	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
178	        String postcode = owner.getPostcode();
179	        if (postcode != null) {
180	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
181	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
182	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
183	            }
184	        }
185	        // The owner's telephone and email are now in their canonical, stored form.
186	        // Establish the household id before the duplicate check so the candidate's whole
187	        // identity key can be compared against the existing owners': only an owner that
188	        // deliberately shares an existing household (same normalized last name and address)
189	        // is assigned that household's shared id; a plain new owner has no household id, so
190	        // its identity key is decided by telephone and email alone.
191	        String lastNameKey = normalizeIdentity(owner.getLastName());
192	        String addressKey = addressNormalizer.normalize(owner.getAddress());
193	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
194	                && householdExists(lastNameKey, addressKey)) {
195	            owner.setHouseholdId(householdId(lastNameKey, addressKey));
196	        }
197	        if (isDuplicateOwner(owner)) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        String cityKey = normalizeIdentity(owner.getCity());
201	        long ownersInCity = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
203	            .count();
204	        if (ownersInCity >= 50) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        owner.setCustomerCode(customerCode(owner));
208	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
209	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
210	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
211	            .count();
212	        owner.setNamesakeCount(namesakeCount);
213	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
214	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
215	        this.clinicService.saveOwner(owner);
216	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
217	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
218	            ownerMapper.membershipLevel(owner));
219	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    /**
226	     * Whether {@code candidate} collides with an already-registered owner under the single
227	     * identity rule enforced on create. This is the one point at which a new owner is
228	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
229	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
230	     * email (or an empty string when absent) and the householdId joined by '|'. The
231	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
232	     * the telephone is part of the key, two members of the same household (same householdId)
233	     * with different telephones have different identityKeys and are both allowed.
234	     *
235	     * <p>The candidate arrives with its telephone and email already normalized and its
236	     * household id already derived, and each existing owner is stored in the same canonical
237	     * form, so an identityKey match means the two owners are genuinely the same identity.
238	     *
239	     * @param candidate the fully-normalized owner about to be created
240	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
241	     */
242	    private boolean isDuplicateOwner(Owner candidate) {
243	        String identityKey = OwnerMapper.identityKey(candidate);
244	        return this.clinicService.findAllOwners().stream()
245	            .map(OwnerMapper::identityKey)
246	            .anyMatch(identityKey::equals);
247	    }
248	
249	    /**
250	     * Whether an existing owner already belongs to the household identified by the given
251	     * normalized last name and address, so a new owner flagged {@code sharesHousehold} has a
252	     * household to join.
253	     */
254	    private boolean householdExists(String lastNameKey, String addressKey) {
255	        return this.clinicService.findAllOwners().stream()
256	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
257	                && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
258	    }
259	
260	    /**
261	     * Normalize a value for household-identity comparison: null becomes an empty
262	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
263	     * to a single space, and the result is lower-cased.
264	     */
265	    private static String normalizeIdentity(String value) {
266	        if (value == null) {
267	            return "";
268	        }
269	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
270	    }
271	
272	    /**
273	     * Build the stable, shared household identifier for an owner, formatted
274	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
275	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
276	     * Owners in the same household (same normalized lastName and address) therefore
277	     * derive an identical householdId.
278	     */
279	    private static String householdId(String lastNameKey, String addressKey) {
280	        return "HH-" + sha256HexPrefix(lastNameKey + "|" + addressKey, 12);
281	    }
282	
283	    /**
284	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
285	     * bytes of {@code source}. This is the single place the SHA-256 hex derivation lives, so
286	     * every identity value built from a truncated hex digest reads the same computation.
287	     */
288	    private static String sha256HexPrefix(String source, int length) {
289	        try {
290	            byte[] digest = MessageDigest.getInstance("SHA-256")
291	                .digest(source.getBytes(StandardCharsets.UTF_8));
292	            StringBuilder sb = new StringBuilder(digest.length * 2);
293	            for (byte b : digest) {
294	                sb.append(String.format("%02x", b));
295	            }
296	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
297	        }
298	        catch (NoSuchAlgorithmException e) {
299	            throw new IllegalStateException("SHA-256 not available", e);
300	        }
301	    }
302	
303	    /**
304	     * Build the customer code assigned to {@code owner} on create, formatted
305	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
306	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
307	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
308	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
309	     */
310	    private String customerCode(Owner owner) {
311	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
312	        String hash8 = sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
313	        return region + "-" + hash8;
314	    }
315	
316	    /**
317	     * Roll a registration date forward to the next business day: a Saturday or Sunday
318	     * advances to the following Monday, and a weekday is returned unchanged.
319	     */
320	    private static LocalDate toBusinessDay(LocalDate date) {
321	        return switch (date.getDayOfWeek()) {
322	            case SATURDAY -> date.plusDays(2);
323	            case SUNDAY -> date.plusDays(1);
324	            default -> date;
325	        };
326	    }
327	
328	    /**
329	     * Build the membership number assigned on create, formatted
330	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
331	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
332	     */
333	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
334	        String yy = String.format("%02d", registrationDate.getYear() % 100);
335	        return customerCode + "-M" + yy;
336	    }
337	
