import org.springframework.samples.petclinic.rest.api.OwnersApi;
import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.PetDto;
import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
import org.springframework.samples.petclinic.rest.dto.VisitDto;
import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    /** Minimal syntactic check for an email address: a non-empty local part, a single
     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
    private static final Pattern EMAIL_PATTERN =
        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");

    /** Dedicated audit logger; emits an audit line on successful owner create. */
    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final TelephoneNormalizer telephoneNormalizer;

    private final AddressNormalizer addressNormalizer;

    private final CityRegionResolver cityRegionResolver;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 TelephoneNormalizer telephoneNormalizer,
                                 AddressNormalizer addressNormalizer,
                                 CityRegionResolver cityRegionResolver) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.telephoneNormalizer = telephoneNormalizer;
        this.addressNormalizer = addressNormalizer;
        this.cityRegionResolver = cityRegionResolver;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        // A supplied registration date may not be later than the server's current date.
        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
        LocalDate registrationDate = owner.getRegistrationDate();
        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
            .map(Owner::getRegistrationDate)
            .filter(registrationDate::equals)
            .count();
        if (ownersCreatedThatDay >= 100) {
            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
        }
        String address = addressNormalizer.normalize(owner.getAddress());
        if (address.isBlank()) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setAddress(address);
        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
        if (telephone == null) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setTelephone(telephone);
        String email = owner.getEmail();
        if (email != null) {
            email = email.trim();
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
            owner.setEmail(email.toLowerCase(Locale.ROOT));
        }
        // A postcode is optional, but when supplied it must be four digits and valid for the
        // owner's city per the fixed region table; a city with no known region accepts any
        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
        String postcode = owner.getPostcode();
        if (postcode != null) {
            if (!POSTCODE_PATTERN.matcher(postcode).matches()
                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
        }
        // The owner's telephone and email are now in their canonical, stored form.
        // Establish the household id before the duplicate check so the candidate's whole
        // identity key can be compared against the existing owners': only an owner that
        // deliberately shares an existing household (same normalized last name and address)
        // is assigned that household's shared id; a plain new owner has no household id, so
        // its identity key is decided by telephone and email alone.
        String lastNameKey = normalizeIdentity(owner.getLastName());
        String addressKey = addressNormalizer.normalize(owner.getAddress());
        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
                && householdExists(lastNameKey, addressKey)) {
            owner.setHouseholdId(householdId(lastNameKey, addressKey));
        }
        if (isDuplicateOwner(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        String cityKey = normalizeIdentity(owner.getCity());
        long ownersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
            .count();
        if (ownersInCity >= 50) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        owner.setCustomerCode(customerCode(owner));
        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
            .count();
        owner.setNamesakeCount(namesakeCount);
        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
        this.clinicService.saveOwner(owner);
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
            ownerMapper.membershipLevel(owner));
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * Whether {@code candidate} collides with an already-registered owner under the single
     * identity rule enforced on create. This is the one point at which a new owner is
     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
     * email (or an empty string when absent) and the householdId joined by '|'. The
     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
     * the telephone is part of the key, two members of the same household (same householdId)
     * with different telephones have different identityKeys and are both allowed.
     *
     * <p>The candidate arrives with its telephone and email already normalized and its
     * household id already derived, and each existing owner is stored in the same canonical
     * form, so an identityKey match means the two owners are genuinely the same identity.
     *
     * @param candidate the fully-normalized owner about to be created
     * @return {@code true} if an existing owner already occupies the candidate's identityKey
     */
    private boolean isDuplicateOwner(Owner candidate) {
        String identityKey = OwnerMapper.identityKey(candidate);
        return this.clinicService.findAllOwners().stream()
            .map(OwnerMapper::identityKey)
            .anyMatch(identityKey::equals);
    }

    /**
     * Whether an existing owner already belongs to the household identified by the given
     * normalized last name and address, so a new owner flagged {@code sharesHousehold} has a
     * household to join.
     */
    private boolean householdExists(String lastNameKey, String addressKey) {
        return this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
                && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
    }

    /**
     * Normalize a value for household-identity comparison: null becomes an empty
     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
     * to a single space, and the result is lower-cased.
     */
    private static String normalizeIdentity(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Build the stable, shared household identifier for an owner, formatted
     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
     * Owners in the same household (same normalized lastName and address) therefore
     * derive an identical householdId.
     */
    private static String householdId(String lastNameKey, String addressKey) {
        return "HH-" + sha256HexPrefix(lastNameKey + "|" + addressKey, 12);
    }

    /**
     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
     * bytes of {@code source}. This is the single place the SHA-256 hex derivation lives, so
     * every identity value built from a truncated hex digest reads the same computation.
     */
    private static String sha256HexPrefix(String source, int length) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(source.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, length).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * Build the customer code assigned to {@code owner} on create, formatted
     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
     */
    private String customerCode(Owner owner) {
        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
        String hash8 = sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
        return region + "-" + hash8;
    }

    /**
     * Roll a registration date forward to the next business day: a Saturday or Sunday
     * advances to the following Monday, and a weekday is returned unchanged.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        return switch (date.getDayOfWeek()) {
            case SATURDAY -> date.plusDays(2);
            case SUNDAY -> date.plusDays(1);
            default -> date;
        };
    }

    /**
     * Build the membership number assigned on create, formatted
     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
     */
    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
        String yy = String.format("%02d", registrationDate.getYear() % 100);
        return customerCode + "-M" + yy;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
}

